/**
 * Fiqh cards: each ruling in plain words, the positions of the four schools where they differ, and its
 * evidence: a verse (opens in the mushaf) or a hadith with its narrator and the books that report it
 * (opens with its full text, grade, explanation and benefits from HadeethEnc and the hadith books).
 */
object Fiqh {
    enum class Kind { QURAN, HADITH, ATHAR, IJMA }
    /** One proof. [by]: the narrator ("عن عائشة رضي الله عنها"); [src]: who reports it and its grade. */
    data class Ev(val kind: Kind, val text: String, val by: String = "", val src: String = "", val s: Int = 0, val a: Int = 0, val key: String = "")
    /**
     * One school's answer: its position [q], the item's own evidence it relies on (indices in [use]),
     * its further evidence [ev], and how it reasons from them [wajh].
     */
    data class Side(val q: String, val use: List<Int> = emptyList(), val ev: List<Ev> = emptyList(), val wajh: String = "")
    /** The four schools: Hanafi, Maliki, Shafi'i, Hanbali, and the view preferred by the verifying scholars, if stated. */
    data class Mz(val hanafi: Side, val maliki: Side, val shafii: Side, val hanbali: Side, val rajih: String = "") {
        val sides get() = listOf(hanafi, maliki, shafii, hanbali)
    }
    data class Item(val text: String, val ev: List<Ev> = emptyList(), val mz: Mz? = null)
    data class Sec(val title: String, val items: List<Item>)
    data class Topic(val id: String, val icon: String, val title: String, val intro: String, val secs: List<Sec>, val links: List<Pair<String, String>> = emptyList())

    private fun i(t: String, vararg ev: Ev, mz: Mz? = null) = Item(t, ev.toList(), mz)
    private fun h(text: String, by: String, src: String, key: String = "") = Ev(Kind.HADITH, text, by, src, key = key)
    private fun q(text: String, s: Int, a: Int) = Ev(Kind.QURAN, text, s = s, a = a)
    private fun at(text: String, by: String, src: String) = Ev(Kind.ATHAR, text, by, src)
    private fun ij(text: String) = Ev(Kind.IJMA, text)
    private fun sd(q: String, use: List<Int>, ev: List<Ev>, wajh: String) = Side(q, use, ev, wajh)

