                    mz = Mz(sd("يُردّ على أصحاب الفروض غير الزوجين.", listOf(), listOf(q("وأولو الأرحام بعضهم أولى ببعض في كتاب الله", 8, 75)), "القرابة أولى من بيت المال."), sd("لبيت المال، وأفتى المتأخرون بالردّ.", listOf(), listOf(), "الفروض مقدّرة فلا يُزاد عليها، والباقي لبيت المال؛ وأفتى المتأخرون بالردّ لعدم انتظام بيت المال."), sd("لبيت المال، وأفتى المتأخرون بالردّ.", listOf(), listOf(), "كالمالكية."), sd("يُردّ على أصحاب الفروض غير الزوجين.", listOf(), listOf(q("وأولو الأرحام بعضهم أولى ببعض في كتاب الله", 8, 75)), "كالحنفية."))),
            )),
        )),
    )

    fun byId(id: String) = topics.firstOrNull { it.id == id }

    data class Hit(val topic: Topic, val sec: Sec, val item: Item)
    fun search(q: String): List<Hit> {
        val words = Quran.normalize(q).split(' ').filter { it.length >= 2 }
        if (words.isEmpty()) return emptyList()
        return topics.flatMap { t -> t.secs.flatMap { s -> s.items.map { Hit(t, s, it) } } }.filter { h ->
            val n = Quran.normalize(h.sec.title + " " + h.item.text + " " + h.item.ev.joinToString(" ") { it.text } + " " + (h.item.mz?.sides?.joinToString(" ") { it.q } ?: ""))
            words.all { n.contains(it) }
        }.take(60)
    }

    /** Words to find a hadith by: the given key, else the first distinctive words of its text. */
    fun keyOf(e: Ev): String {
        if (e.key.isNotBlank()) return e.key
        val stop = setOf("قال", "رسول", "الله", "صلى", "عليه", "وسلم", "عن", "في", "من", "ان", "ما", "لا", "اذا", "ثم", "او", "على")
        return Quran.normalize(e.text).replace(Regex("[^ء-ي\\s]"), " ").split(' ').filter { it.length >= 2 && it !in stop }.take(4).joinToString(" ")
    }
}

private val mzNames = listOf("الحنفية", "المالكية", "الشافعية", "الحنابلة")
private val mzColors = listOf(0xFF2E7D5B, 0xFF8A5A14, 0xFF2D5BA8, 0xFF8E2F55)

/** The relied-upon books of each school, where its positions are taken from. */
private val mzBooks = listOf(
    "الهداية للمرغيناني، وردّ المحتار (حاشية ابن عابدين)",
    "مختصر خليل، والشرح الكبير للدردير مع حاشية الدسوقي",
    "منهاج الطالبين للنووي، وتحفة المحتاج لابن حجر الهيتمي، ونهاية المحتاج للرملي",
    "الإقناع للحجاوي، ومنتهى الإرادات لابن النجار، وشرحهما كشاف القناع للبهوتي",
)

/** The four schools: each one's position, then (on tap) its own evidence, how it reasons, and its books; then the preferred view. */
@Composable
private fun MadhahibBox(m: Fiqh.Mz, itemEv: List<Fiqh.Ev>, open: (Fiqh.Ev) -> Unit) {
    var shown by remember(m) { mutableStateOf(-1) }
    Column(Modifier.fillMaxWidth().clip(L.shape(12.dp)).background(P.card).padding(8.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Sub("أقوال المذاهب الأربعة وأدلتها", color = P.gold, size = 12.sp)
        m.sides.forEachIndexed { k, side ->
            val evs = side.use.mapNotNull { itemEv.getOrNull(it) } + side.ev
            val isOpen = shown == k
            Column(Modifier.fillMaxWidth().clip(L.shape(10.dp)).background(P.surface).border(1.dp, Color(mzColors[k]).copy(alpha = if (isOpen) .7f else .25f), L.shape(10.dp))
                .clickable { shown = if (isOpen) -1 else k }.padding(8.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Row(verticalAlignment = Alignment.Top) {
                    Text(mzNames[k], color = Color.White, fontSize = 11.sp, fontWeight = FontWeight.Bold,
                        modifier = Modifier.width(62.dp).clip(L.shape(8.dp)).background(Color(mzColors[k])).padding(horizontal = 6.dp, vertical = 3.dp))
                    Text(side.q, color = P.ink, fontSize = (14 * Data.textScale).sp, lineHeight = (22 * Data.textScale).sp, modifier = Modifier.weight(1f).padding(start = 8.dp))
                }
                if (!isOpen) Text(if (evs.isEmpty() && side.wajh.isBlank()) "المصدر ▾" else "أدلتهم ووجه الاستدلال (${Quran.digits(evs.size)}) ▾", color = Color(mzColors[k]), fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                else {
                    if (side.wajh.isNotBlank()) Column {
                        Sub("وجه الاستدلال", color = Color(mzColors[k]), size = 12.sp)
                        Text(side.wajh, color = P.ink, fontSize = (14 * Data.textScale).sp, lineHeight = (22 * Data.textScale).sp)
                    }
                    if (evs.isNotEmpty()) Sub("أدلتهم (اضغط على الدليل لعرضه)", color = Color(mzColors[k]), size = 12.sp)
                    evs.forEach { e -> EvidenceRow(e, open) }
                    Text("المعتمد في المذهب: ${mzBooks[k]}", color = P.muted, fontSize = 11.sp, lineHeight = 16.sp)
                }
            }
        }
        if (m.rajih.isNotBlank()) Column(Modifier.fillMaxWidth().clip(L.shape(10.dp)).background(P.accent.copy(alpha = .10f)).padding(8.dp)) {
            Sub("الترجيح", color = P.accent, size = 12.sp)
            Text(m.rajih, color = P.ink, fontSize = (14 * Data.textScale).sp, lineHeight = (22 * Data.textScale).sp)
        }
    }
}

/** One proof, tappable: a verse opens in the mushaf, a hadith or athar opens its own page. */
@Composable
private fun EvidenceRow(e: Fiqh.Ev, open: (Fiqh.Ev) -> Unit) {
    val (icon, label) = when (e.kind) {
        Fiqh.Kind.QURAN -> "📖" to "آية: ${Quran.surahs.getOrNull(e.s - 1)?.name ?: ""} ${Quran.digits(e.a)}"
        Fiqh.Kind.HADITH -> "📜" to "حديث"
        Fiqh.Kind.ATHAR -> "🗒" to "أثر"
        Fiqh.Kind.IJMA -> "🤝" to "إجماع"
    }
    val tappable = e.kind != Fiqh.Kind.IJMA
    Column(Modifier.fillMaxWidth().clip(L.shape(12.dp)).background(P.accent.copy(alpha = .07f)).border(1.dp, P.accent.copy(alpha = .25f), L.shape(12.dp))
        .then(if (tappable) Modifier.clickable { open(e) } else Modifier).padding(horizontal = 10.dp, vertical = 8.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            GText("$icon $label", color = P.accent, fontSize = 12.sp, fontWeight = FontWeight.Bold)
            if (e.by.isNotBlank()) Text(" · ${e.by}", color = P.muted, fontSize = 11.sp, maxLines = 1, overflow = TextOverflow.Ellipsis, modifier = Modifier.weight(1f))
            else androidx.compose.foundation.layout.Spacer(Modifier.weight(1f))
            if (tappable) Text("‹", color = P.accent, fontSize = 16.sp)
        }
        Text(if (e.kind == Fiqh.Kind.IJMA) e.text else "«${e.text}»", color = P.ink, fontSize = (15 * Data.textScale).sp, lineHeight = (25 * Data.textScale).sp, fontFamily = Fonts.naskh, maxLines = 3, overflow = TextOverflow.Ellipsis)
        if (e.src.isNotBlank()) Text(e.src, color = P.gold, fontSize = 11.sp)
    }
}

/** A hadith or athar given as evidence: its text, narrator and source, then its full text, grade, explanation and benefits. */
@Composable
fun FiqhEvidencePage(e: Fiqh.Ev, back: () -> Unit) {
    val ctx = LocalContext.current
    androidx.activity.compose.BackHandler(onBack = back)
    var openSharh by rememberSaveable { mutableStateOf<String?>(null) }
    var openBook by rememberSaveable { mutableStateOf<Pair<String, String>?>(null) }
    var searchAll by rememberSaveable { mutableStateOf(false) }
    openSharh?.let { SharhOpen(it) { openSharh = null }; return }
    openBook?.let { (b, n) -> HadithReader(b, 0, { openBook = null }, focus = n); return }
    val key = remember(e) { Fiqh.keyOf(e) }
    if (searchAll) { HadithSearchPage(initial = key) { searchAll = false }; return }
    var sharh by remember(e) { mutableStateOf<List<HadithSearch.Hit>?>(null) }
    var books by remember(e) { mutableStateOf<List<HadithSearch.Hit>?>(null) }
    LaunchedEffect(e) {
        withContext(Dispatchers.IO) {
            // The most words that still find it: fewer words when the exact wording differs, but never
            // fewer than three (two common words like «هو الطهور» match other hadiths).
            val words = key.split(' ').filter { it.isNotBlank() }
            // A key chosen by hand is used whole: better nothing than another hadith.
            val least = if (e.key.isNotBlank()) words.size else minOf(3, words.size)
            var s = emptyList<HadithSearch.Hit>()
            for (n in words.size downTo least) { s = runCatching { HadithSearch.searchSharh(ctx, words.take(n).joinToString(" "), 8) }.getOrDefault(emptyList()); if (s.isNotEmpty()) break }
            sharh = s
            var b = emptyList<HadithSearch.Hit>()
            for (n in words.size downTo least) { b = runCatching { HadithSearch.searchBooks(ctx, words.take(n).joinToString(" "), 12) }.getOrDefault(emptyList()); if (b.isNotEmpty()) break }
            books = b
        }
    }
    Subpage(if (e.kind == Fiqh.Kind.ATHAR) "الأثر" else "الحديث", back) {
        Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            Panel(color = P.card) {
                Text("«${e.text}»", color = P.ink, fontSize = (19 * Data.textScale).sp, lineHeight = (33 * Data.textScale).sp, fontFamily = Fonts.naskh)
                if (e.by.isNotBlank()) Row(Modifier.padding(top = 8.dp)) { Sub("الراوي: ", color = P.gold); Text(e.by, color = P.ink, fontSize = 14.sp, modifier = Modifier.weight(1f)) }
                if (e.src.isNotBlank()) Row(Modifier.padding(top = 4.dp)) { Sub("المصدر والدرجة: ", color = P.gold); Text(e.src, color = P.ink, fontSize = 14.sp, modifier = Modifier.weight(1f)) }
            }
            Title("💡 الشرح والفوائد والدرجة")
            when (val s = sharh) {
                null -> Box(Modifier.fillMaxWidth().padding(12.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = P.accent) }
                else -> if (s.isEmpty()) Sub("لم أجده في موسوعة الأحاديث المشروحة (تحتاج الإنترنت أول مرة). جرّب البحث الكامل في الأسفل.")
                else s.forEachIndexed { k, hit ->
                    Column(Modifier.fillMaxWidth().clip(L.shape(14.dp)).background(if (k == 0) P.accent.copy(alpha = .12f) else P.surface).clickable { hit.sharhId?.let { openSharh = it } }.padding(12.dp)) {
                        Text(hit.text, color = P.ink, fontSize = 15.sp, fontFamily = Fonts.naskh, lineHeight = 25.sp, maxLines = 4, overflow = TextOverflow.Ellipsis)
                        Sub(if (k == 0) "افتح: نص الحديث والدرجة والشرح والفوائد ومعاني الكلمات ›" else "افتح الشرح ›", size = 12.sp, color = P.accent)
                    }
                }
            }
            Title("📚 في كتب الحديث على هاتفك")
            when (val b = books) {
                null -> Box(Modifier.fillMaxWidth().padding(12.dp), contentAlignment = Alignment.Center) { CircularProgressIndicator(color = P.accent) }
                else -> if (b.isEmpty()) Sub("لم أجده في الكتب المنزّلة. نزّل صحيح البخاري ومسلم وغيرهما من «المكتبة › الحديث» ليظهر هنا برقمه.")
                else b.forEach { hit ->
                    Column(Modifier.fillMaxWidth().clip(L.shape(14.dp)).background(P.surface).border(1.dp, P.line, L.shape(14.dp)).clickable { openBook = hit.book to hit.number }.padding(12.dp)) {
                        Text(hit.text, color = P.ink, fontSize = 15.sp, fontFamily = Fonts.naskh, lineHeight = 25.sp, maxLines = 5, overflow = TextOverflow.Ellipsis)
                        Text("${hit.bookTitle} · رقم ${hit.number}", color = P.gold, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
                    }
                }
            }
            Action("🔍 بحث كامل عن هذا الحديث", Modifier.fillMaxWidth(), filled = false) { searchAll = true }
        }
    }
}

/** All the fiqh cards with a search over them. [open] opens a page by id ("fiqh:<id>", "salah", "zakat"…). */
@Composable
fun FiqhHome(open: (String) -> Unit) {
    var q by rememberSaveable { mutableStateOf("") }
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        OutlinedTextField(q, { q = it }, singleLine = true, modifier = Modifier.fillMaxWidth(), placeholder = { Text("ابحث في الأحكام: نواقض الوضوء، المسح، الكفارة…") })
        if (q.isNotBlank()) {
            val hits = Fiqh.search(q)
            if (hits.isEmpty()) Sub("لا نتائج. جرّب كلمة أخرى.")
            hits.forEach { h ->
                Column(Modifier.fillMaxWidth().clip(L.shape(14.dp)).background(P.surface).clickable { open("fiqh:${h.topic.id}") }.padding(12.dp)) {
                    Sub("${h.topic.title} › ${h.sec.title}", color = P.gold, size = 12.sp)
                    Text(h.item.text, color = P.ink, fontSize = 15.sp, lineHeight = 24.sp)
                }
            }
            return@Column
        }
        Sub("كل حكم مع دليله: اضغط على الحديث لترى نصه وراويه ومن أخرجه ودرجته وشرحه وفوائده، وعلى الآية لتفتحها في المصحف. وحيث اختلف العلماء تجد أقوال المذاهب الأربعة.", size = 12.sp)
        Fiqh.topics.forEach { t ->
            Row(Modifier.fillMaxWidth().clip(L.shape(16.dp)).background(P.surface).clickable { open("fiqh:${t.id}") }.padding(14.dp), verticalAlignment = Alignment.CenterVertically) {
                Glyph(t.icon, tint = P.accent, size = 28.dp)
                Column(Modifier.weight(1f).padding(horizontal = 12.dp)) {
                    Text(t.title, color = P.ink, fontSize = 17.sp, fontWeight = FontWeight.SemiBold)
                    Sub(t.secs.joinToString(" · ") { it.title }, size = 12.sp)
                }
                Text("›", color = P.muted, fontSize = 20.sp)
            }
        }
        Row(Modifier.fillMaxWidth().clip(L.shape(16.dp)).background(P.surface).clickable { open("salah") }.padding(14.dp), verticalAlignment = Alignment.CenterVertically) {
            Glyph("💧", tint = P.accent, size = 28.dp)
            Column(Modifier.weight(1f).padding(horizontal = 12.dp)) {
                Text("صفة الوضوء والصلاة", color = P.ink, fontSize = 17.sp, fontWeight = FontWeight.SemiBold)
                Sub("الوضوء والصلاة خطوة خطوة، وسجود السهو، وصلاة المسافر والمريض", size = 12.sp)
            }
            Text("›", color = P.muted, fontSize = 20.sp)
        }
    }
}

@Composable
