                    s.items.forEach { item ->
                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Row {
                                Text("•", color = P.accent, fontSize = 18.sp, modifier = Modifier.padding(end = 8.dp))
                                Text(item.text, color = P.ink, fontSize = (15 * Data.textScale).sp, lineHeight = (25 * Data.textScale).sp, fontWeight = FontWeight.Medium, modifier = Modifier.weight(1f))
                            }
                            item.mz?.let { MadhahibBox(it, item.ev) { x -> if (x.kind == Fiqh.Kind.QURAN) Nav.overlayQuran = x.s to x.a else ev = x } }
                            item.ev.forEach { e ->
                                EvidenceRow(e) { x -> if (x.kind == Fiqh.Kind.QURAN) Nav.overlayQuran = x.s to x.a else ev = x }
                            }
                        }
                    }
                }
            }
        }
        if (t.links.isNotEmpty()) Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            t.links.forEach { (label, to) -> Choice(label, false) { open(to) } }
        }
        Sub("ملخّص ميسّر من كتب الفقه المقارن؛ وأقوال المذاهب على المعتمد عند كلٍّ منها. للمسائل الخاصة اسأل أهل العلم.", Modifier.padding(4.dp), size = 11.sp)
    }
}
